-- Exercise XP+ : Students table (PostgreSQL)
-- Run CREATE DATABASE separately, outside a transaction.
CREATE DATABASE bootcamp;

-- Connect to bootcamp in pgAdmin, open its Query Tool, then run the rest.

-- Create 2-3: Create students with an automatically generated primary key.
CREATE TABLE students (
    id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    last_name VARCHAR(100) NOT NULL,
    first_name VARCHAR(100) NOT NULL,
    birth_date DATE NOT NULL
);

-- Insert 1: Insert all six students with one statement.
-- The exercise dates use DD/MM/YYYY; SQL dates below use YYYY-MM-DD.
INSERT INTO students (first_name, last_name, birth_date)
VALUES
    ('Marc', 'Benichou', DATE '1998-11-02'),
    ('Yoan', 'Cohen', DATE '2010-12-03'),
    ('Lea', 'Benichou', DATE '1987-07-27'),
    ('Amelia', 'Dux', DATE '1996-04-07'),
    ('David', 'Grez', DATE '2003-06-14'),
    ('Omer', 'Simpson', DATE '1980-10-03');

-- Insert 2: Replace the placeholders, then uncomment to insert your details.
-- On a fresh table, this insert receives id 7; RETURNING displays the id.
-- INSERT INTO students (last_name, first_name, birth_date)
-- VALUES ('YOUR_LAST_NAME', 'YOUR_FIRST_NAME', DATE 'YYYY-MM-DD')
-- RETURNING id;

-- Select 1: Fetch every column for all students.
SELECT *
FROM students;

-- Select 2: Fetch only first names and last names.
SELECT first_name, last_name
FROM students;

-- Select 3.1: Fetch the student with id 2.
SELECT first_name, last_name
FROM students
WHERE id = 2;

-- Select 3.2: Match both the last name Benichou and the first name Marc.
SELECT first_name, last_name
FROM students
WHERE last_name = 'Benichou' AND first_name = 'Marc';

-- Select 3.3: Match either the last name Benichou or the first name Marc.
SELECT first_name, last_name
FROM students
WHERE last_name = 'Benichou' OR first_name = 'Marc';

-- Select 3.4: Find first names containing a (case-insensitive).
SELECT first_name, last_name
FROM students
WHERE first_name ILIKE '%a%';

-- Select 3.5: Find first names starting with a (includes Amelia).
SELECT first_name, last_name
FROM students
WHERE first_name ILIKE 'a%';

-- Select 3.6: Find first names ending with a.
SELECT first_name, last_name
FROM students
WHERE first_name ILIKE '%a';

-- Select 3.7: Find first names whose second-to-last letter is a.
-- The underscore matches exactly one final character.
SELECT first_name, last_name
FROM students
WHERE first_name ILIKE '%a_';

-- Select 3.8: Fetch both students with ids 1 and 3.
-- One row cannot have id = 1 AND id = 3; IN matches either requested id.
SELECT first_name, last_name
FROM students
WHERE id IN (1, 3);

-- Select 4: Fetch all details for students born on or after January 1, 2000.
SELECT *
FROM students
WHERE birth_date >= DATE '2000-01-01';
